import React, { useEffect, useState } from "react";
import styled from "styled-components";

const PageContainer = styled.div`
  min-height: 100vh;
  padding: ${(p) => p.theme.spacing.lg};
  background: ${(p) => p.theme.colors.background};
`;

const Grid = styled.div`
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: ${(p) => p.theme.spacing.lg};
`;

const Card = styled.div`
  background: ${(p) => p.theme.colors.white};
  border-radius: ${(p) => p.theme.borderRadius.medium};
  box-shadow: 0 4px 10px rgba(0, 0, 0, 0.05);
  overflow: hidden;
  display: flex;
  flex-direction: column;
`;

const ImageWrapper = styled.div`
  width: 100%;
  aspect-ratio: 4 / 3;
  background: ${(p) => p.theme.colors.gray.light};
  overflow: hidden;

  img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    display: block;
  }
`;

const CardBody = styled.div`
  padding: ${(p) => p.theme.spacing.md};
`;

const Name = styled.h3`
  margin: 0 0 ${(p) => p.theme.spacing.xs};
  color: ${(p) => p.theme.colors.secondary};
  font-size: ${(p) => p.theme.typography.fontSizes.medium};
`;

const City = styled.p`
  margin: 0 0 ${(p) => p.theme.spacing.xs};
  color: ${(p) => p.theme.colors.gray.dark};
  font-size: ${(p) => p.theme.typography.fontSizes.small};
`;

const Description = styled.p`
  margin: 0;
  color: ${(p) => p.theme.colors.gray.dark};
  font-size: ${(p) => p.theme.typography.fontSizes.small};
`;

type Business = {
  _id: string;
  businessName: string;
  description?: string;
  city?: string;
  imageUrl?: string;
};

const SalonListTest: React.FC = () => {
  const [salons, setSalons] = useState<Business[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchSalons = async () => {
      try {
        setError(null);
        setLoading(true);

        const res = await fetch("http://localhost:5000/api/public/businesses");
        const data = await res.json();

        // Log raw data so you can see exact fields
        console.log("Raw /api/public/businesses data:", data);

        const rawList = Array.isArray(data) ? data : data.businesses || [];

        // Map to our Business type, being flexible with field names
        const list: Business[] = rawList.map((item: any) => ({
          _id: item._id,
          businessName: item.businessName || item.name || "Unnamed salon",
          description: item.description || item.about || "",
          city: item.city || "",
          imageUrl: item.imageUrl || item.coverImage || "",
        }));

        console.log("Mapped salons:", list);
        setSalons(list);
      } catch (err: any) {
        console.error("Error loading salons:", err);
        setError("Failed to load salons");
      } finally {
        setLoading(false);
      }
    };

    fetchSalons();
  }, []);

  return (
    <PageContainer>
      <h1>Salon Card Test</h1>

      {loading && <p>Loading salons...</p>}
      {error && <p style={{ color: "red" }}>{error}</p>}

      <Grid>
        {salons.map((salon) => {
          // Build image src: handle both relative (/uploads/...) and absolute URLs
          const imgSrc = salon.imageUrl
            ? salon.imageUrl.startsWith("http")
              ? salon.imageUrl
              : `http://localhost:5000${salon.imageUrl}`
            : null;

          return (
            <Card key={salon._id}>
              <ImageWrapper>
                {imgSrc ? (
                  <img
                    src={imgSrc}
                    alt={salon.businessName}
                    onError={(e) => {
                      console.warn("Image failed to load:", imgSrc);
                      (e.currentTarget as HTMLImageElement).style.display =
                        "none";
                    }}
                  />
                ) : null}
              </ImageWrapper>
              <CardBody>
                <Name>{salon.businessName}</Name>
                {salon.city && <City>{salon.city}</City>}
                {salon.description && (
                  <Description>{salon.description}</Description>
                )}
              </CardBody>
            </Card>
          );
        })}
      </Grid>
    </PageContainer>
  );
};

export default SalonListTest;
